if (element.querySelector('.admin-dashboard-notice')) return;
var box = document.createElement('div');
box.className = 'admin-dashboard-notice';
box.style.cssText = 'background:#fff3cd;border:2px solid #ffc107;border-radius:8px;padding:16px 20px;margin-bottom:20px;font-weight:bold;';
var link = document.createElement('a');
link.href = '/admin';
link.target = '_blank';
link.style.cssText = 'color:#856404;text-decoration:underline;font-size:1.1em;';
link.textContent = 'Admin Dashboard';
var text = document.createTextNode(' Configure settings yourself: ');
var instructions = document.createElement('span');
instructions.style.color = '#856404';
instructions.textContent = ' Click the link above to open your wiki\'s Admin Dashboard and enable/disable features like Article Comments, Blogs, Message Wall, and more.';
box.appendChild(link);
box.appendChild(text);
box.appendChild(instructions);
element.insertBefore(box, element.firstChild);
